import{_ as e,o,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-06-24:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-06-24:: Ceph Orchestration Meeting","date":"2019-06-24T00:00:00.000Z","updated":"2019-06-28T00:00:00.000Z","tags":["Ceph","Orchestrator","RGW","Rook","CI/CD"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-06-24_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-06-24_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-06-24_-_-_Ceph_Orchestration_Meeting.md"};function a(i,t,p,_,l,c){return o(),r("div",null,[...t[0]||(t[0]=[n("<p>在2019年6月24日的Ceph Orchestration Meeting中，Orchestrator团队成员讨论了多个关键议题：</p><ol><li><p><strong>RGW区域设置讨论</strong>：会议中提到了在实施RGW区域设置时遇到的问题，特别是配置Amazon S3组时的复杂性。团队成员讨论了Rook的设计，并决定将节点管理和配置分开处理，同时邀请Matt Benjamin团队的人员参与审查和提供建议。</p></li><li><p><strong>Orchestrator自命名空间包</strong>：讨论了将Python代码抽取到公共包中的想法，但由于可能带来的风险和代码重构，决定在Sebastian返回后，再次会议讨论。</p></li><li><p><strong>Rook进展</strong>：Sebastian介绍了Rook的最新进展，包括连接外部集群和部署NFS的PR，并讨论了其中的冲突。</p></li><li><p><strong>治理和CI/CD</strong>：讨论了治理的更新，以及如何处理CI/CD中的问题，包括Skip CI标志和构建失败的情况。</p></li><li><p><strong>基于PVC的OSD设计</strong>：讨论了基于PVC的OSD设计进展，以及设备集的考虑。</p></li><li><p><strong>OSD重设计</strong>：讨论了Peter提出的OSD重设计，包括合并冲突和功能不匹配等问题，并提出了使用命令运行器框架和Semoran检查器的建议。</p></li></ol><p>会议还确定了后续行动计划，包括与Matt Benjamin团队沟通、讨论Orchestrator自命名空间包、推进Rook的PR、解决CI/CD中的问题、完成基于PVC的OSD设计和OSD重设计。</p>",3)])])}const C=e(s,[["render",a]]);export{h as __pageData,C as default};
